INSERT INTO "changelog_entry" ("entry_date", "summary") VALUES
('2026-11-24', 'La fiche d''un objet de la Prêtothèque va droit au but : la photo, ce qu''il faut savoir (état, où le récupérer, consignes de sécurité bien visibles), puis tout de suite le calendrier pour l''emprunter. Les outils du propriétaire (photos, exemplaires, étiquette) sont rangés sous « Gérer mon objet ». Ajouter un objet est plus court : l''essentiel d''abord, le reste sous « Plus de détails », et la « Section » s''appelle désormais « Catégorie ». Les Réglages se rangent en quatre onglets (Profil, Notifications, Calendriers, Écussons) et les cases à cocher s''enregistrent toutes seules.');
